"""Tests for the deployment supplied de-identification of outgoing datasets.

A gateway must apply the deployment supplied de-identification operation
before a dataset leaves the receiving process. The two supported C-STORE
entry points are covered using the same synthetic dataset:

* direct C-STORE requests sent using ``Association.send_c_store()``
* the C-STORE sub-operations generated by the Query/Retrieve SCP when
  handling a C-GET or C-MOVE request

The receiving peer is a stand-in that records the actual bytes passed to the
DIMSE provider, so the checks are on what would be sent over the network.
"""

from copy import deepcopy
from io import BytesIO
import queue

import pytest

from pydicom.dataset import Dataset, FileMetaDataset
from pydicom.uid import ExplicitVRLittleEndian

from pynetdicom import AE, DeidentificationError, _config, evt
from pynetdicom._deid import deidentify_dataset, error_comment
from pynetdicom._globals import MODE_ACCEPTOR, MODE_REQUESTOR
from pynetdicom.association import Association
from pynetdicom.dimse_primitives import C_GET, C_MOVE, C_STORE
from pynetdicom.dsutils import decode, encode
from pynetdicom.presentation import PresentationContext
from pynetdicom.service_class import QueryRetrieveServiceClass
from pynetdicom.sop_class import (
    CTImageStorage,
    PatientRootQueryRetrieveInformationModelGet,
    PatientRootQueryRetrieveInformationModelMove,
)

from .utils import get_port

PATIENT_ID = "MRN-1234567890"
PATIENT_NAME = "IDENTIFIED^Patient"
PATIENT_BIRTH_DATE = "19700101"
SOP_INSTANCE_UID = "1.2.826.0.1.3680043.11.1"
STUDY_UID = "1.2.826.0.1.3680043.11.2"
SERIES_UID = "1.2.826.0.1.3680043.11.3"
DEIDENTIFIED_NAME = "ANONYMOUS"
DEIDENTIFIED_ID = ""

QUERY = Dataset()
QUERY.QueryRetrieveLevel = "PATIENT"
QUERY.PatientName = "*"


def synthetic_dataset():
    """Return a new synthetic dataset for the tests."""
    ds = Dataset()
    ds.file_meta = FileMetaDataset()
    ds.file_meta.MediaStorageSOPClassUID = CTImageStorage
    ds.file_meta.MediaStorageSOPInstanceUID = SOP_INSTANCE_UID
    ds.file_meta.TransferSyntaxUID = ExplicitVRLittleEndian
    ds.SOPClassUID = CTImageStorage
    ds.SOPInstanceUID = SOP_INSTANCE_UID
    ds.PatientName = PATIENT_NAME
    ds.PatientID = PATIENT_ID
    ds.PatientBirthDate = PATIENT_BIRTH_DATE
    ds.StudyInstanceUID = STUDY_UID
    ds.SeriesInstanceUID = SERIES_UID
    ds.Modality = "CT"
    ds.InstanceNumber = 1

    return ds


def deidentify(ds):
    """Return a de-identified copy of `ds`.

    The deep copy makes sure the original dataset isn't mutated by the
    operation, as it may still be needed by the sender.
    """
    ds = deepcopy(ds)
    ds.PatientName = DEIDENTIFIED_NAME
    ds.PatientID = DEIDENTIFIED_ID
    ds.PatientBirthDate = ""

    return ds


def failing_deidentify(ds):
    """Raise part-way through the conversion."""
    ds = deepcopy(ds)
    ds.PatientName = DEIDENTIFIED_NAME
    # Partially converted dataset - the operation is then interrupted
    raise RuntimeError("pseudonymisation service unavailable")


def encoded(ds, transfer_syntax=ExplicitVRLittleEndian):
    """Return `ds` encoded using `transfer_syntax`."""
    return encode(
        ds,
        transfer_syntax.is_implicit_VR,
        transfer_syntax.is_little_endian,
        transfer_syntax.is_deflated,
    )


def make_context(context_id, abstract_syntax, transfer_syntax, as_scu, as_scp):
    """Return an accepted presentation context."""
    context = PresentationContext()
    context.context_id = context_id
    context.abstract_syntax = abstract_syntax
    context.transfer_syntax = [transfer_syntax]
    context._as_scu = as_scu
    context._as_scp = as_scp

    return context


class StubDIMSE:
    """A receiving peer stand-in that records the primitives it's given."""

    def __init__(self):
        """Create a new stand-in."""
        self.sent = []
        self.cancel_req = {}
        self.msg_queue = queue.Queue()
        self._store_rsp_pending = False

    def send_msg(self, primitive, context_id):
        """Record the primitive instead of encoding and sending it."""
        self.sent.append((primitive, context_id))
        self._store_rsp_pending = isinstance(primitive, C_STORE)

    def get_msg(self, block=False):
        """Return a successful C-STORE response."""
        assert self._store_rsp_pending
        self._store_rsp_pending = False
        rsp = C_STORE()
        rsp.MessageID = 1
        rsp.MessageIDBeingRespondedTo = 1
        rsp.Status = 0x0000
        rsp.AffectedSOPClassUID = CTImageStorage
        rsp.AffectedSOPInstanceUID = SOP_INSTANCE_UID
        rsp.DataSet = None

        return 1, rsp

    def store_requests(self):
        """Return the recorded C-STORE request primitives."""
        return [pr for pr, _ in self.sent if isinstance(pr, C_STORE)]


def requestor(ae):
    """Return a requestor association set up for sending CT images."""
    assoc = Association(ae, MODE_REQUESTOR)
    assoc.is_established = True
    assoc._is_paused = True
    assoc._accepted_cx = {
        1: make_context(1, CTImageStorage, ExplicitVRLittleEndian, True, False)
    }
    assoc.dimse = StubDIMSE()

    return assoc


def qr_scp(ae, model):
    """Return an acceptor association acting as a Query/Retrieve SCP."""
    assoc = Association(ae, MODE_ACCEPTOR)
    assoc.is_established = True
    assoc._is_paused = True
    assoc._accepted_cx = {
        1: make_context(1, model, ExplicitVRLittleEndian, True, False),
        # The role selected context used for the C-STORE sub-operations
        3: make_context(3, CTImageStorage, ExplicitVRLittleEndian, True, False),
    }
    assoc.dimse = StubDIMSE()

    return assoc


def get_request():
    """Return a C-GET request primitive."""
    req = C_GET()
    req.MessageID = 99
    req.AffectedSOPClassUID = PatientRootQueryRetrieveInformationModelGet
    req.Priority = 2
    req.Identifier = BytesIO(encoded(QUERY))

    return req


def move_request():
    """Return a C-MOVE request primitive."""
    req = C_MOVE()
    req.MessageID = 99
    req.MoveDestination = "DEST"
    req.AffectedSOPClassUID = PatientRootQueryRetrieveInformationModelMove
    req.Priority = 2
    req.Identifier = BytesIO(encoded(QUERY))

    return req


def responses(assoc, response_type):
    """Return the recorded response primitives of `response_type`."""
    return [pr for pr, _ in assoc.dimse.sent if isinstance(pr, response_type)]


class TestDeidentifyDataset:
    """Tests for the de-identification helper."""

    def test_no_deidentifier(self):
        """Test the dataset is returned unchanged when no operation is set."""
        ds = synthetic_dataset()
        assert deidentify_dataset(ds, None) is ds

    def test_success(self):
        """Test a successful conversion."""
        ds = synthetic_dataset()
        out = deidentify_dataset(ds, deidentify)
        assert out is not ds
        assert out.PatientName == DEIDENTIFIED_NAME
        assert out.PatientID == DEIDENTIFIED_ID
        # The original dataset is left untouched
        assert ds.PatientName == PATIENT_NAME
        assert ds.PatientID == PATIENT_ID

    @pytest.mark.parametrize("result", [None, "not a dataset", 42])
    def test_bad_result(self, result):
        """Test an unusable return value is a failure."""
        with pytest.raises(DeidentificationError, match="De-identification failed"):
            deidentify_dataset(synthetic_dataset(), lambda _: result)

    def test_raises(self):
        """Test an exception from the de-identifier is reported."""
        with pytest.raises(DeidentificationError) as exc:
            deidentify_dataset(synthetic_dataset(), failing_deidentify)

        assert "pseudonymisation service unavailable" in exc.value.reason
        assert exc.value.sop_instance_uid == SOP_INSTANCE_UID

    def test_missing_required_element(self):
        """Test the returned dataset must be a usable C-STORE dataset."""

        def remove_uid(ds):
            ds = deidentify(ds)
            del ds.SOPInstanceUID
            return ds

        with pytest.raises(DeidentificationError, match="SOPInstanceUID"):
            deidentify_dataset(synthetic_dataset(), remove_uid)

    def test_missing_file_meta(self):
        """Test the returned dataset must have a transfer syntax."""

        def remove_meta(ds):
            ds = deidentify(ds)
            del ds.file_meta.TransferSyntaxUID
            return ds

        with pytest.raises(DeidentificationError, match="Transfer Syntax UID"):
            deidentify_dataset(synthetic_dataset(), remove_meta)

    def test_error_comment_truncated(self):
        """Test the error comment fits in the DIMSE element."""
        assert len(error_comment("a" * 100)) == 64


class TestAEDeidentifier:
    """Tests for the AE.deidentifier property."""

    def test_default(self):
        """Test the default is no de-identification."""
        assert AE().deidentifier is None

    def test_set(self):
        """Test a callable can be set."""
        ae = AE()
        ae.deidentifier = deidentify
        assert ae.deidentifier is deidentify

    def test_bad_type(self):
        """Test a non-callable is rejected."""
        with pytest.raises(TypeError, match="must be a callable"):
            AE().deidentifier = "not callable"


class TestSendCStoreDeidentification:
    """Tests for the direct C-STORE entry point."""

    def setup_method(self):
        """Run prior to each test"""
        _config.STORE_SEND_CHUNKED_DATASET = False

    def teardown_method(self):
        """Reset the configuration"""
        _config.STORE_SEND_CHUNKED_DATASET = False

    def test_sent_bytes_are_deidentified(self):
        """Test the peer receives the de-identified bytes, not the original."""
        ae = AE()
        ae.deidentifier = deidentify
        assoc = requestor(ae)

        ds = synthetic_dataset()
        status = assoc.send_c_store(ds)
        assert status.Status == 0x0000

        stores = assoc.dimse.store_requests()
        assert len(stores) == 1
        raw = stores[0].DataSet.getvalue()

        # The actual bytes are an encoding of the de-identified dataset
        assert raw == encoded(deidentify(synthetic_dataset()))

        # Compare decoded values as well as the raw bytes
        sent = decode(BytesIO(raw), False, True)
        assert sent.PatientName == DEIDENTIFIED_NAME
        assert sent.PatientID == DEIDENTIFIED_ID
        assert sent.PatientBirthDate == ""
        assert sent.SOPClassUID == CTImageStorage
        assert sent.SOPInstanceUID == SOP_INSTANCE_UID

        # The original values must not appear anywhere in the encoded dataset
        assert PATIENT_NAME.encode() not in raw
        assert PATIENT_ID.encode() not in raw
        assert PATIENT_BIRTH_DATE.encode() not in raw

        # The caller's dataset is not modified
        assert ds.PatientName == PATIENT_NAME
        assert ds.PatientID == PATIENT_ID

    def test_deidentified_uid_used(self):
        """Test the de-identified UIDs are used for the request parameters."""

        def new_uids(ds):
            ds = deidentify(ds)
            ds.SOPInstanceUID = "1.2.826.0.1.3680043.11.99"
            ds.StudyInstanceUID = "1.2.826.0.1.3680043.11.98"
            return ds

        ae = AE()
        ae.deidentifier = new_uids
        assoc = requestor(ae)

        assoc.send_c_store(synthetic_dataset())
        store = assoc.dimse.store_requests()[0]
        assert store.AffectedSOPInstanceUID == "1.2.826.0.1.3680043.11.99"

    def test_failure_sends_nothing(self):
        """Test no C-STORE request is sent when the conversion fails."""
        ae = AE()
        ae.deidentifier = failing_deidentify
        assoc = requestor(ae)

        with pytest.raises(DeidentificationError) as exc:
            assoc.send_c_store(synthetic_dataset())

        assert "pseudonymisation service unavailable" in exc.value.reason
        assert exc.value.sop_instance_uid == SOP_INSTANCE_UID
        # Nothing was sent to the peer
        assert assoc.dimse.sent == []

    @pytest.mark.parametrize("result", [None, "not a dataset"])
    def test_bad_result_sends_nothing(self, result):
        """Test no C-STORE request is sent when the result is unusable."""
        ae = AE()
        ae.deidentifier = lambda _: result
        assoc = requestor(ae)

        with pytest.raises(DeidentificationError):
            assoc.send_c_store(synthetic_dataset())

        assert assoc.dimse.sent == []

    def test_no_transfer_syntax_fallback(self):
        """Test the original values aren't sent using another syntax.

        The de-identifier removes the transfer syntax, which can't be fixed by
        renegotiating or converting to another transfer syntax, so the
        operation fails without sending anything.
        """

        def break_meta(ds):
            ds = deidentify(ds)
            del ds.file_meta.TransferSyntaxUID
            return ds

        ae = AE()
        ae.deidentifier = break_meta
        assoc = requestor(ae)

        with pytest.raises(DeidentificationError, match="Transfer Syntax UID"):
            assoc.send_c_store(synthetic_dataset())

        assert assoc.dimse.sent == []

    def test_chunked_file_is_decoded(self):
        """Test a file path is decoded when a de-identifier is set.

        Chunked sending bypasses decoding, so it can't be used when the
        dataset has to be de-identified.
        """
        import tempfile
        from pathlib import Path

        ae = AE()
        ae.deidentifier = deidentify
        assoc = requestor(ae)

        with tempfile.TemporaryDirectory() as tmp:
            path = Path(tmp) / "test.dcm"
            synthetic_dataset().save_as(path, enforce_file_format=True)

            _config.STORE_SEND_CHUNKED_DATASET = True
            status = assoc.send_c_store(str(path))

        assert status.Status == 0x0000
        raw = assoc.dimse.store_requests()[0].DataSet.getvalue()
        assert PATIENT_NAME.encode() not in raw
        assert DEIDENTIFIED_NAME.encode() in raw


class TestGetSubOperationDeidentification:
    """Tests for de-identification of C-GET C-STORE sub-operations."""

    def _run_get(self, ae):
        """Run a C-GET through the SCP using the stand-in peer."""
        assoc = qr_scp(ae, PatientRootQueryRetrieveInformationModelGet)
        ds = synthetic_dataset()

        def handle_get(event):
            yield 1
            yield 0xFF00, ds

        assoc.bind(evt.EVT_C_GET, handle_get)
        service = QueryRetrieveServiceClass(assoc)
        service.SCP(get_request(), assoc._accepted_cx[1])

        return assoc

    def test_sub_operation_bytes_are_deidentified(self):
        """Test the peer receives the same de-identified bytes as a direct send."""
        ae = AE()
        ae.deidentifier = deidentify

        # Direct C-STORE bytes
        direct = requestor(ae)
        direct.send_c_store(synthetic_dataset())
        direct_bytes = direct.dimse.store_requests()[0].DataSet.getvalue()

        # C-GET sub-operation bytes
        assoc = self._run_get(ae)
        stores = assoc.dimse.store_requests()
        assert len(stores) == 1
        sub_bytes = stores[0].DataSet.getvalue()

        assert sub_bytes == direct_bytes
        assert sub_bytes == encoded(deidentify(synthetic_dataset()))

        sent = decode(BytesIO(sub_bytes), False, True)
        assert sent.PatientName == DEIDENTIFIED_NAME
        assert sent.PatientID == DEIDENTIFIED_ID
        assert PATIENT_NAME.encode() not in sub_bytes
        assert PATIENT_ID.encode() not in sub_bytes

        final = responses(assoc, C_GET)[-1]
        assert final.Status == 0x0000
        assert final.NumberOfCompletedSuboperations == 1
        assert final.NumberOfFailedSuboperations == 0

    def test_failed_sub_operation_sends_nothing(self):
        """Test a failed conversion sends no C-STORE and is in the summary."""
        ae = AE()
        ae.deidentifier = failing_deidentify

        assoc = self._run_get(ae)

        # No C-STORE sub-operation was sent
        assert assoc.dimse.store_requests() == []

        final = responses(assoc, C_GET)[-1]
        assert final.Status == 0xA702
        assert final.NumberOfFailedSuboperations == 1
        assert final.NumberOfCompletedSuboperations == 0
        identifier = decode(final.Identifier, False, True)
        assert identifier.FailedSOPInstanceUIDList == SOP_INSTANCE_UID

        # The failure is explained in the response
        assert final.ErrorComment == (
            "De-identification failed: pseudonymisation service unavailable"
        )


class TestMoveSubOperationDeidentification:
    """Tests for de-identification of C-MOVE C-STORE sub-operations."""

    def _run_move(self, ae):
        """Run a C-MOVE through the SCP using stand-in peers."""
        assoc = qr_scp(ae, PatientRootQueryRetrieveInformationModelMove)

        store_assoc = requestor(ae)
        store_assoc.release = lambda: setattr(store_assoc, "is_released", True)
        ae.associate = lambda *args, **kwargs: store_assoc

        ds = synthetic_dataset()

        def handle_move(event):
            yield ("127.0.0.1", 11113)
            yield 1
            yield 0xFF00, ds

        assoc.bind(evt.EVT_C_MOVE, handle_move)
        service = QueryRetrieveServiceClass(assoc)
        service.SCP(move_request(), assoc._accepted_cx[1])

        return assoc, store_assoc

    def test_sub_operation_bytes_are_deidentified(self):
        """Test the move destination receives only de-identified bytes."""
        ae = AE()
        ae.deidentifier = deidentify

        assoc, store_assoc = self._run_move(ae)

        stores = store_assoc.dimse.store_requests()
        assert len(stores) == 1
        raw = stores[0].DataSet.getvalue()
        assert raw == encoded(deidentify(synthetic_dataset()))
        assert PATIENT_NAME.encode() not in raw

        final = responses(assoc, C_MOVE)[-1]
        assert final.Status == 0x0000
        assert final.NumberOfCompletedSuboperations == 1

    def test_failed_sub_operation_sends_nothing(self):
        """Test a failed conversion sends no C-STORE and is in the summary."""
        ae = AE()
        ae.deidentifier = failing_deidentify

        assoc, store_assoc = self._run_move(ae)

        assert store_assoc.dimse.store_requests() == []

        final = responses(assoc, C_MOVE)[-1]
        assert final.Status == 0xA702
        assert final.NumberOfFailedSuboperations == 1
        identifier = decode(final.Identifier, False, True)
        assert identifier.FailedSOPInstanceUIDList == SOP_INSTANCE_UID
        assert final.ErrorComment.startswith("De-identification failed")


class TestNetworkDeidentification:
    """Network based end-to-end checks.

    These require the ability to bind to a local port, and are skipped when
    the environment doesn't allow it.
    """

    def setup_method(self):
        """Run prior to each test"""
        self.ae = None

    def teardown_method(self):
        """Clear any active threads"""
        if self.ae:
            self.ae.shutdown()

    def _start_scp(self, handle_store):
        self.ae = ae = AE()
        ae.acse_timeout = 5
        ae.dimse_timeout = 5
        ae.network_timeout = 5
        ae.add_supported_context(CTImageStorage)
        try:
            server = ae.start_server(
                ("localhost", get_port()),
                block=False,
                evt_handlers=[(evt.EVT_C_STORE, handle_store)],
            )
        except PermissionError:
            pytest.skip("Local port binding is unavailable")

        return ae, server

    def test_direct_c_store(self):
        """Test a direct C-STORE is received de-identified."""
        received = []

        def handle_store(event):
            received.append(event.dataset)
            return 0x0000

        ae, server = self._start_scp(handle_store)
        ae.deidentifier = deidentify
        ae.add_requested_context(CTImageStorage, ExplicitVRLittleEndian)
        assoc = ae.associate("localhost", get_port())
        assert assoc.is_established

        status = assoc.send_c_store(synthetic_dataset())
        assert status.Status == 0x0000
        assoc.release()
        server.shutdown()

        assert len(received) == 1
        assert received[0].PatientName == DEIDENTIFIED_NAME
        assert received[0].PatientID == DEIDENTIFIED_ID
